print(f"Length: {len(target)}")

# Parse pairs
stack = []
pairs = {}
for i, c in enumerate(target):
    if c == '(':
        stack.append(i)
    elif c == ')':
        j = stack.pop()
        pairs[j] = i
        pairs[i] = j

print(f"Number of pairs: {len(pairs)//2}")

# Find lonely pairs (isolated - not stacked with neighbors)
lonely = []
for i in sorted(pairs.keys()):
    if i < pairs[i]:  # only count each pair once
        is_lonely = True
        # check if stacked with neighbor
        if i-1 in pairs and i+1 in pairs:
            if pairs[i-1] == pairs[i]+1 and pairs[i+1] == pairs[i]-1:
                is_lonely = False
        if is_lonely:
            lonely.append((i, pairs[i]))
print(f"Lonely pairs: {len(lonely)}")
for l, r in lonely:
    print(f"  ({l},{r})")

# Find all stems (consecutive stacked pairs)
stems = []
for i in sorted(pairs.keys()):
    if i < pairs[i]:
        # check if it's the start of a stem
        if i-1 not in pairs or pairs.get(i-1) != pairs[i]+1:
            # start of a new stem
            stem = [(i, pairs[i])]
            j = i+1
            while j in pairs and j < pairs[j] and pairs.get(j) == stem[-1][1]-1:
                stem.append((j, pairs[j]))
                j += 1
            stems.append(stem)

print(f"Stems: {len(stems)}")
for idx, s in enumerate(stems):
    print(f"  stem {idx}: {len(s)} pairs, from ({s[0][0]},{s[0][1]}) to ({s[-1][0]},{s[-1][1]})")

# Find unpaired regions
